<?php
declare(strict_types=1);
$root=dirname(__DIR__);require_once $root.'/config/config.php';require_once $root.'/includes/services/AllianceService.php';
$pdo=db();$players=$pdo->query('SELECT id,alliance_id FROM players WHERE alliance_id IS NULL ORDER BY id LIMIT 2')->fetchAll(PDO::FETCH_ASSOC);if(count($players)<1){fwrite(STDERR,"alliance_participant_missing\n");exit(2);} $creator=(int)$players[0]['id'];$joiner=count($players)>1?(int)$players[1]['id']:null;$suffix=substr(str_replace('.','',uniqid('',true)),-8);$name='Test Alliance '.$suffix;$tag='T'.substr(strtoupper(preg_replace('/[^A-Z0-9]/','',$suffix)),0,5);if(strlen($tag)<2)$tag='TST';$service=new AllianceService($pdo);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id IN (".$creator.($joiner?', '.$joiner:'').") AND cooldown_key IN ('alliance_create','alliance_join')")->execute();$allianceId=$service->create($creator,$name,$tag,'transactional contract test');$q=$pdo->prepare('SELECT founder_id,name,tag FROM alliances WHERE id=?');$q->execute([$allianceId]);$alliance=$q->fetch(PDO::FETCH_ASSOC);$m=$pdo->prepare('SELECT role FROM alliance_members WHERE alliance_id=? AND player_id=?');$m->execute([$allianceId,$creator]);$checks=['created'=>is_array($alliance)&&$alliance['founder_id']==$creator&&$alliance['name']===$name&&$alliance['tag']===$tag,'creator_membership'=>$m->fetchColumn()==='leader'];$membership=null;if($joiner){$membership=$service->join($joiner,$allianceId);$m->execute([$allianceId,$joiner]);$checks['join_success']=($membership['state']??'')==='success';$checks['member_membership']=$m->fetchColumn()==='member';$checks['capacity_reported']=(int)$membership['capacity']>=(int)$membership['member_count'];}$event=$pdo->prepare("SELECT payload FROM game_events WHERE player_id=? AND event_type='alliance_created' AND entity_id=? ORDER BY id DESC LIMIT 1");$event->execute([$creator,$allianceId]);$payload=json_decode((string)$event->fetchColumn(),true);$checks['audit_metadata']=is_array($payload)&&isset($payload['capacity'],$payload['name'],$payload['tag']);$pdo->prepare('DELETE FROM alliance_members WHERE alliance_id=?')->execute([$allianceId]);$pdo->prepare('DELETE FROM alliances WHERE id=?')->execute([$allianceId]);$pdo->prepare('UPDATE players SET alliance_id=NULL WHERE id IN ('. $creator . ($joiner?','.$joiner:'') .')')->execute();$pdo->prepare("DELETE FROM game_events WHERE entity_type='alliance' AND entity_id=?")->execute([$allianceId]);$pdo->prepare("DELETE FROM player_cooldowns WHERE player_id IN (".$creator.($joiner?', '.$joiner:'').") AND cooldown_key IN ('alliance_create','alliance_join')")->execute();$failures=array_keys(array_filter($checks,static fn(bool $ok):bool=>!$ok));echo json_encode(['status'=>$failures?'failed':'passed','alliance_id'=>$allianceId,'membership'=>$membership,'checks'=>$checks,'failures'=>$failures],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($failures?1:0);
